base:
:root{color-scheme:dark}
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
body{margin:0;background:#101010;color:#e9e9e9;font-family:'Geist',-apple-system,system-ui,sans-serif;font-size:15px;line-height:1.55;-webkit-font-smoothing:antialiased}
.eos-page{box-sizing:border-box;max-width:1064px;margin:0 auto;padding:28px 32px}
img{max-width:100%;height:auto;display:block}
a{color:inherit}
[data-part]{break-inside:avoid}
.eos-image-missing{display:flex;align-items:flex-end;box-sizing:border-box;min-height:120px;padding:10px 12px;border-radius:3px;background:rgba(127,127,127,.14);font-size:13px;opacity:.85}
.eos-filters{display:flex;flex-wrap:wrap;gap:6px;margin:18px 0}
.eos-filters button,.eos-button,.eos-ask{display:inline-flex;align-items:center;box-sizing:border-box;height:30px;padding:0 12px;border-radius:8px;border:1px solid rgba(127,127,127,.38);background:transparent;color:inherit;font:inherit;font-size:13px;text-decoration:none;cursor:pointer}
.eos-filters button[aria-pressed=true]{background:rgba(127,127,127,.22)}
.eos-filters button:focus-visible,.eos-button:focus-visible,.eos-ask:focus-visible{outline:2px solid #6d8bff;outline-offset:2px}
[data-filter-hidden]{display:none!important}
.eos-disclosure>summary{cursor:pointer}
.eos-secret{font-family:'IBM Plex Mono',ui-monospace,monospace;letter-spacing:.12em}
.eos-pointing [data-part]{cursor:crosshair}
.eos-pointing [data-part]:hover{outline:1px dashed rgba(109,139,255,.8);outline-offset:3px}
.eos-pointed,.eos-pointing .eos-pointed:hover{outline:2px solid #6d8bff;outline-offset:3px}
.eos-live[data-stale]{opacity:.6}
@media print{body{background:#fff;color:#000}.eos-page{max-width:none;padding:0}.eos-filters,.eos-button,.eos-ask{display:none}}

style:
/* The Morning Build: a light sheet of paper, serif text, mono labels. */
.sheet { --paper: #eceae4; --ink: #161616; --soft: #2c2b28; --muted: #55534d; --rule: #b9b6ad; --accent: #1f3fbf; }
header, main, section, footer { display: block; }
div, p, h1, h2, h3, ul, li, figure, article, aside { box-sizing: border-box; }
.sheet { max-width: 1000px; margin: 0 auto; border-radius: 6px; background: var(--paper); color: var(--ink); font-family: 'Fraunces', Georgia, 'Times New Roman', serif; box-shadow: 0 30px 80px rgba(0, 0, 0, 0.55); }
header { padding: 34px 44px 0; }
.dateline { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 4px 16px; font-family: 'IBM Plex Mono', ui-monospace, monospace; font-size: 12px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--muted); }
.name { margin: 10px 0 0; padding: 14px 0 12px; border-top: 3px solid var(--ink); border-bottom: 1px solid var(--ink); text-align: center; font-size: clamp(40px, 6vw, 68px); line-height: 1; font-weight: 700; letter-spacing: -0.03em; }
.summary { margin: 0; padding: 7px 0; border-bottom: 1px solid var(--ink); text-align: center; font-family: 'IBM Plex Mono', ui-monospace, monospace; font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--muted); }
.front { display: flex; flex-wrap: wrap; padding: 22px 44px 0; }
.lead { flex: 2.2 1 420px; min-width: 0; padding-right: 28px; }
.kicker { margin: 0; font-family: 'IBM Plex Mono', ui-monospace, monospace; font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: var(--accent); }
.quiet { color: var(--muted); }
.lead h2 { margin: 6px 0 0; font-size: clamp(30px, 3.6vw, 44px); line-height: 1.04; font-weight: 600; letter-spacing: -0.02em; text-wrap: balance; }
h2 a, h3 a { color: var(--ink); text-decoration: none; }
.dek { margin: 12px 0 0; font-size: 18px; line-height: 1.45; color: var(--soft); }
figure { margin: 16px 0 0; }
figure img { width: 100%; height: auto; border-radius: 3px; object-fit: cover; aspect-ratio: 16 / 9; }
figcaption { font-family: 'IBM Plex Mono', ui-monospace, monospace; font-size: 12px; color: var(--muted); padding-top: 4px; }
.body { margin: 14px 0 0; font-size: 16px; line-height: 1.6; color: var(--soft); }
.rail { flex: 1 1 240px; min-width: 0; padding-left: 28px; border-left: 1px solid var(--rule); display: flex; flex-direction: column; gap: 18px; }
.rail p { margin: 6px 0 0; font-size: 16px; line-height: 1.4; }
.rail a { color: var(--accent); text-underline-offset: 3px; font-family: 'Geist', system-ui, sans-serif; font-size: 14px; }
.starred { margin: 0; padding: 16px 0 0 18px; border-top: 1px solid var(--rule); }
.starred li { margin: 6px 0 0; font-size: 16px; line-height: 1.4; }
.note { font-family: 'Geist', system-ui, sans-serif; color: var(--muted); }
.stories { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 24px; padding: 18px 44px 30px; border-top: 1px solid var(--ink); }
.story h3 { margin: 6px 0 0; font-size: 20px; line-height: 1.2; font-weight: 600; }
.story p { margin: 8px 0 0; font-size: 16px; line-height: 1.45; color: var(--soft); }
.story time { display: block; margin-top: 6px; font-family: 'IBM Plex Mono', ui-monospace, monospace; font-size: 12px; color: var(--muted); }
.feedback { display: flex; gap: 10px; justify-content: center; padding: 18px 44px 28px; }
.sheet .eos-filters { padding: 0 44px; }
@media (max-width: 600px) {
  header, .front, .stories, .feedback { padding-left: 20px; padding-right: 20px; }
  .lead { padding-right: 0; }
  .rail { padding-left: 0; border-left: 0; }
}
@media print {
  .sheet { box-shadow: none; border-radius: 0; }
  .feedback { display: none; }
}

runtime:
// Eos's page runtime: the only script a page frame runs. The frame has no
// network and no same origin; this script talks to the dashboard by
// postMessage alone, and reads messages only from the window that framed it.
// It never builds markup from data: a swapped part is HTML the core drew.
(function () {
  "use strict";
  var parentWindow = window.parent;
  var mode = "read";
  var seen = {};
  var readParts = [];
  var readLinks = [];
  var readTimer = null;

  function post(type, body) {
    var message = { type: type };
    for (var key in body) message[key] = body[key];
    parentWindow.postMessage(message, "*");
  }

  function partOf(node) {
    while (node && node.nodeType === 1) {
      if (node.hasAttribute("data-part")) return node;
      node = node.parentNode;
    }
    return null;
  }

  function indexOf(el) {
    var index = el && el.getAttribute("data-index");
    return index === null || index === undefined ? null : Number(index);
  }

  function flushReads() {
    readTimer = null;
    if (!readParts.length && !readLinks.length) return;
    post("eos-page/read", { parts: readParts, links: readLinks });
    readParts = [];
    readLinks = [];
  }

  function noteRead(part, index, link) {
    var key = part + "#" + index + "#" + (link || "");
    if (seen[key]) return;
    seen[key] = true;
    if (link) readLinks.push({ part: part, index: index, link: link });
    else readParts.push({ part: part, index: index });
    if (!readTimer) readTimer = setTimeout(flushReads, 1500);
  }

  function filter(chip) {
    var bar = chip.parentNode;
    var of = bar.getAttribute("data-filters");
    var value = chip.getAttribute("data-filter");
    var chips = bar.querySelectorAll("button[data-filter]");
    for (var i = 0; i < chips.length; i++) chips[i].setAttribute("aria-pressed", chips[i] === chip ? "true" : "false");
    var items = document.querySelectorAll("[data-filter-of]");
    for (var j = 0; j < items.length; j++) {
      if (items[j].getAttribute("data-filter-of") !== of) continue;
      var shown = value === "" || items[j].getAttribute("data-filter-value") === value;
      if (shown) items[j].removeAttribute("data-filter-hidden");
      else items[j].setAttribute("data-filter-hidden", "");
    }
  }

  function point(target) {
    var part = partOf(target);
    if (!part) return;
    var marked = document.querySelectorAll(".eos-pointed");
    for (var i = 0; i < marked.length; i++) marked[i].classList.remove("eos-pointed");
    part.classList.add("eos-pointed");
    var r = part.getBoundingClientRect();
    post("eos-page/part", {
      part: part.getAttribute("data-part"),
      index: indexOf(part),
      rect: { x: r.left, y: r.top, width: r.width, height: r.height }
    });
  }

  document.addEventListener("click", function (event) {
    var target = event.target;
    if (mode === "point") {
      event.preventDefault();
      event.stopPropagation();
      point(target);
      return;
    }
    var chip = target.closest && target.closest("button[data-filter]");
    if (chip) {
      filter(chip);
      return;
    }
    var button = target.closest && target.closest("button[data-button],button[data-ask]");
    if (button) {
      post("eos-page/act", {
        button: button.getAttribute("data-button") || button.getAttribute("data-ask"),
        ask: button.hasAttribute("data-ask"),
        index: indexOf(partOf(button))
      });
      return;
    }
    var link = target.closest && target.closest("a[href]");
    if (link) {
      event.preventDefault();
      var href = link.getAttribute("href");
      var part = partOf(link);
      if (part) noteRead(part.getAttribute("data-part"), indexOf(part), href);
      post("eos-page/open", { href: href });
    }
  }, true);

  document.addEventListener("toggle", function (event) {
    var part = partOf(event.target);
    if (part && event.target.open) noteRead(part.getAttribute("data-part"), indexOf(part), null);
  }, true);

  document.addEventListener("keydown", function (event) {
    if (mode === "point" && event.key === "Escape") post("eos-page/mode", { mode: "read" });
  });

  if (window.IntersectionObserver) {
    var observer = new IntersectionObserver(function (entries) {
      for (var i = 0; i < entries.length; i++) {
        if (!entries[i].isIntersecting) continue;
        var el = entries[i].target;
        noteRead(el.getAttribute("data-part"), indexOf(el), null);
        observer.unobserve(el);
      }
    }, { threshold: 0.6 });
    var parts = document.querySelectorAll("[data-part]");
    for (var k = 0; k < parts.length; k++) observer.observe(parts[k]);
  }

  window.addEventListener("message", function (event) {
    if (event.source !== parentWindow) return;
    var data = event.data || {};
    if (data.type === "eos-page/mode" && (data.mode === "read" || data.mode === "point" || data.mode === "edit")) {
      mode = data.mode;
      document.documentElement.classList.toggle("eos-pointing", mode === "point");
      if (mode !== "point") {
        var marked = document.querySelectorAll(".eos-pointed");
        for (var i = 0; i < marked.length; i++) marked[i].classList.remove("eos-pointed");
      }
    } else if (data.type === "eos-page/swap" && typeof data.part === "string" && typeof data.html === "string") {
      var old = document.querySelector('[data-live][data-part="' + data.part.replace(/[^a-z0-9-]/g, "") + '"]');
      if (!old) return;
      var holder = document.createElement("template");
      holder.innerHTML = data.html;
      var next = holder.content.firstElementChild;
      if (next && next.getAttribute("data-part") === old.getAttribute("data-part")) old.replaceWith(next);
    }
  });

  function size() {
    post("eos-page/size", { height: document.documentElement.scrollHeight });
  }
  if (window.ResizeObserver) new ResizeObserver(size).observe(document.documentElement);
  window.addEventListener("load", size);
  // The Live parts the dashboard fills and keeps current: their names only.
  var live = [];
  var liveParts = document.querySelectorAll("[data-live][data-part]");
  for (var l = 0; l < liveParts.length; l++) live.push(liveParts[l].getAttribute("data-part"));
  post("eos-page/ready", { live: live });
})();
